-- Fase 9b: países y monedas, con los 9 países principales (los demás llegan en la migración siguiente, solo con datos).
-- Todo se agrega sin borrar nada: los viajes, pagos y usuarios que ya existen quedan en Colombia (CO, COP), y las tablas
-- de tarifas de antes (time_and_distance_values, vehicle_rates) se conservan sin uso por si hay que volver atrás.
-- Las tablas que se alteran son pequeñas (cientos de filas): los ALTER se hacen en segundos.
-- Para deshacer: borrar las columnas nuevas de client_requests, payments y users, volver payments.amount a INT
-- y borrar las seis tablas nuevas.

-- Monedas: decimales que usa y, para el precio de un flete, el paso de los botones + y − y los límites
CREATE TABLE `currencies` (
    `code` CHAR(3) NOT NULL,
    `decimals` TINYINT NOT NULL,
    `fare_step` DOUBLE NOT NULL,
    `min_fare` DOUBLE NOT NULL,
    `max_fare` DOUBLE NOT NULL,
    PRIMARY KEY (`code`),
    CONSTRAINT `currencies_decimals_check` CHECK (`decimals` BETWEEN 0 AND 3),
    CONSTRAINT `currencies_fare_check` CHECK (`fare_step` > 0 AND `min_fare` > 0 AND `max_fare` > `min_fare`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

INSERT INTO `currencies` (`code`, `decimals`, `fare_step`, `min_fare`, `max_fare`) VALUES
    ('COP', 0, 1000, 5000, 10000000),
    ('MXN', 2, 5, 50, 100000),
    ('USD', 2, 1, 5, 5000),
    ('EUR', 2, 1, 5, 5000),
    ('BRL', 2, 2, 10, 25000);

-- Tarifas base del precio sugerido en cada moneda. Un país nuevo arranca con las de su moneda (no hay que inventarle
-- tarifas); si el admin le cambia las suyas en el panel, quedan en country_rates
CREATE TABLE `currency_rates` (
    `currency_code` CHAR(3) NOT NULL,
    `km_value` DOUBLE NOT NULL,
    `min_value` DOUBLE NOT NULL,
    `weight_rate` DOUBLE NOT NULL,
    `size_rate` DOUBLE NOT NULL,
    `commission_rate` DOUBLE NOT NULL DEFAULT 0.1,
    PRIMARY KEY (`currency_code`),
    CONSTRAINT `currency_rates_commission_check` CHECK (`commission_rate` >= 0 AND `commission_rate` <= 0.5),
    CONSTRAINT `currency_rates_currency_code_fkey` FOREIGN KEY (`currency_code`) REFERENCES `currencies` (`code`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Los pesos siguen con las tarifas que tenía Colombia (o las de siempre en una base nueva)
INSERT INTO `currency_rates` (`currency_code`, `km_value`, `min_value`, `weight_rate`, `size_rate`, `commission_rate`)
    SELECT 'COP', `km_value`, `min_value`, `weight_rate`, `size_rate`, `commission_rate` FROM `time_and_distance_values` WHERE `id` = 1
    UNION ALL
    SELECT 'COP', 2000, 150, 150, 8000, 0.1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `time_and_distance_values` WHERE `id` = 1);

-- Valores de partida a precios locales; el admin los ajusta en el panel
INSERT INTO `currency_rates` (`currency_code`, `km_value`, `min_value`, `weight_rate`, `size_rate`, `commission_rate`) VALUES
    ('MXN', 15, 4, 1, 60, 0.1),
    ('USD', 1.5, 0.5, 0.05, 5, 0.1),
    ('EUR', 1.2, 0.4, 0.05, 4, 0.1),
    ('BRL', 3, 0.8, 0.2, 15, 0.1);

-- Tarifa base y factor de cada tipo de vehículo, por moneda (antes: vehicle_rates, solo en pesos)
CREATE TABLE `currency_vehicle_rates` (
    `currency_code` CHAR(3) NOT NULL,
    `vehicle_type` ENUM('CARRY', 'ESTACAS', 'FURGON', 'CAMION') NOT NULL,
    `base_fare` DOUBLE NOT NULL,
    `km_factor` DOUBLE NOT NULL,
    PRIMARY KEY (`currency_code`, `vehicle_type`),
    CONSTRAINT `currency_vehicle_rates_currency_code_fkey` FOREIGN KEY (`currency_code`) REFERENCES `currencies` (`code`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

INSERT INTO `currency_vehicle_rates` (`currency_code`, `vehicle_type`, `base_fare`, `km_factor`)
    SELECT 'COP', `vehicle_type`, `base_fare`, `km_factor` FROM `vehicle_rates`;

-- Los factores son los mismos de los pesos; la base va en cada moneda (CARRY, ESTACAS, FURGON, CAMION)
INSERT INTO `currency_vehicle_rates` (`currency_code`, `vehicle_type`, `base_fare`, `km_factor`)
    SELECT C.`code`, V.`vehicle_type`,
        CASE C.`code`
            WHEN 'MXN' THEN ELT(FIELD(V.`vehicle_type`, 'CARRY', 'ESTACAS', 'FURGON', 'CAMION'), 250, 350, 500, 900)
            WHEN 'USD' THEN ELT(FIELD(V.`vehicle_type`, 'CARRY', 'ESTACAS', 'FURGON', 'CAMION'), 30, 40, 60, 100)
            WHEN 'EUR' THEN ELT(FIELD(V.`vehicle_type`, 'CARRY', 'ESTACAS', 'FURGON', 'CAMION'), 25, 35, 50, 90)
            WHEN 'BRL' THEN ELT(FIELD(V.`vehicle_type`, 'CARRY', 'ESTACAS', 'FURGON', 'CAMION'), 60, 90, 130, 220)
        END,
        V.`km_factor`
    FROM `currencies` AS C CROSS JOIN `currency_vehicle_rates` AS V
    WHERE C.`code` <> 'COP' AND V.`currency_code` = 'COP';

-- Países donde opera FleteYa. Agregar un país es agregar una fila con su área: usa las tarifas de su moneda.
-- names: el nombre en cada idioma de la app. default_language: el idioma con que arranca alguien de ese país.
-- phone_pattern: el celular sin indicativo (Estados Unidos y Puerto Rico comparten el +1, por eso no es único).
-- plate_pattern: null = cualquier placa de 2 a 10 letras o números.
-- area: el territorio (Natural Earth 1:10m, ver scripts/countries/build-areas.mjs). Un punto fuera de todas las áreas
-- es de un país sin FleteYa: ahí no se pueden pedir fletes
CREATE TABLE `countries` (
    `code` CHAR(2) NOT NULL,
    `names` JSON NOT NULL,
    `currency_code` CHAR(3) NOT NULL,
    `default_language` VARCHAR(5) NOT NULL,
    `phone_prefix` VARCHAR(5) NOT NULL,
    `phone_pattern` VARCHAR(60) NOT NULL,
    `phone_example` VARCHAR(15) NOT NULL,
    `plate_pattern` VARCHAR(60) NULL,
    `area` MULTIPOLYGON NULL SRID 4326,
    PRIMARY KEY (`code`),
    INDEX `countries_currency_code_idx` (`currency_code`),
    CONSTRAINT `countries_currency_code_fkey` FOREIGN KEY (`currency_code`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

