ALTER TABLE `countries` MODIFY `area` MULTIPOLYGON NOT NULL SRID 4326;

-- Tarifas propias de un país, solo si el admin las cambió en el panel. Sin fila, el país usa las de su moneda
CREATE TABLE `country_rates` (
    `country_code` CHAR(2) NOT NULL,
    `km_value` DOUBLE NOT NULL,
    `min_value` DOUBLE NOT NULL,
    `weight_rate` DOUBLE NOT NULL,
    `size_rate` DOUBLE NOT NULL,
    `commission_rate` DOUBLE NOT NULL DEFAULT 0.1,
    PRIMARY KEY (`country_code`),
    CONSTRAINT `country_rates_commission_check` CHECK (`commission_rate` >= 0 AND `commission_rate` <= 0.5),
    CONSTRAINT `country_rates_country_code_fkey` FOREIGN KEY (`country_code`) REFERENCES `countries` (`code`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `country_vehicle_rates` (
    `country_code` CHAR(2) NOT NULL,
    `vehicle_type` ENUM('CARRY', 'ESTACAS', 'FURGON', 'CAMION') NOT NULL,
    `base_fare` DOUBLE NOT NULL,
    `km_factor` DOUBLE NOT NULL,
    PRIMARY KEY (`country_code`, `vehicle_type`),
    CONSTRAINT `country_vehicle_rates_country_code_fkey` FOREIGN KEY (`country_code`) REFERENCES `countries` (`code`) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Cada flete guarda el país donde se recoge y su moneda al crearse; ya no cambian.
-- El DEFAULT solo sirve para llenar los que ya existen (todos se negociaron en pesos) y se quita enseguida:
-- un flete nuevo siempre dice su país
ALTER TABLE `client_requests`
    ADD COLUMN `country_code` CHAR(2) NOT NULL DEFAULT 'CO',
    ADD COLUMN `currency` CHAR(3) NOT NULL DEFAULT 'COP';
ALTER TABLE `client_requests`
    ALTER COLUMN `country_code` DROP DEFAULT,
    ALTER COLUMN `currency` DROP DEFAULT,
    ADD INDEX `client_requests_country_code_idx` (`country_code`),
    ADD INDEX `client_requests_currency_idx` (`currency`),
    ADD CONSTRAINT `client_requests_country_code_fkey` FOREIGN KEY (`country_code`) REFERENCES `countries` (`code`) ON DELETE RESTRICT ON UPDATE CASCADE,
    ADD CONSTRAINT `client_requests_currency_fkey` FOREIGN KEY (`currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT ON UPDATE CASCADE;

-- Los pagos guardan su moneda, y el monto admite centavos (EUR, USD...). DOUBLE guarda exactos los INT de antes
ALTER TABLE `payments`
    ADD COLUMN `currency` CHAR(3) NOT NULL DEFAULT 'COP',
    MODIFY `amount` DOUBLE NOT NULL;
ALTER TABLE `payments`
    ALTER COLUMN `currency` DROP DEFAULT,
    ADD INDEX `payments_currency_idx` (`currency`),
    ADD CONSTRAINT `payments_currency_fkey` FOREIGN KEY (`currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT ON UPDATE CASCADE;

-- País de cada usuario: lo elige con el indicativo de su celular. Las cuentas que ya existen son de Colombia
ALTER TABLE `users`
    ADD COLUMN `country_code` CHAR(2) NOT NULL DEFAULT 'CO',
    ADD INDEX `users_country_code_idx` (`country_code`),
    ADD CONSTRAINT `users_country_code_fkey` FOREIGN KEY (`country_code`) REFERENCES `countries` (`code`) ON DELETE RESTRICT ON UPDATE CASCADE;
